input.new_string:
[[ $4 =~ ^[0-9]{8}$ ]] || { echo "rotate: stamp must be YYYYMMDD; nothing done" >&2; exit 2; }
[ "$(cd "$1" && pwd -P)" != "$(mkdir -p "$2" && cd "$2" && pwd -P)" ] || { echo "rotate: log dir and archive dir must differ; nothing done" >&2; exit 2; }
rotate_local "$1" "$3"

